const body = $input.first().json.body;
const provider = body.provider || 'imap';
const email = body.email;
const password = body.password;
const imapHost = body.imap_host;
const imapPort = body.imap_port || 993;
const smtpHost = body.smtp_host;
const smtpPort = body.smtp_port || 587;

if (!email) {
  return [{ json: { success: false, error: 'Email address is required' } }];
}

return [{
  json: {
    provider,
    email,
    password,
    imap_host: imapHost,
    imap_port: imapPort,
    smtp_host: smtpHost,
    smtp_port: smtpPort
  }
}];

// Gmail uses OAuth - return instructions for the user
return [{
  json: {
    success: true,
    provider: 'gmail',
    action_required: 'oauth',
    instructions: 'To connect Gmail, please visit the following URL and authorize GEIVS access to your account.',
    oauth_url: process.env.GMAIL_OAUTH_URL || 'Not configured — set GMAIL_OAUTH_URL in your .env file'
  }
}];

// Test IMAP connection
const input = $input.first().json;

// Write credentials to GEIVS state
const fs = require('fs');
const statePath = '/etc/geivs/geivs-state.json';

try {
  const state = JSON.parse(fs.readFileSync(statePath, 'utf8'));
  state.integrations.email = {
    configured: true,
    provider: input.provider,
    address: input.email,
    imap_host: input.imap_host,
    imap_port: input.imap_port,
    smtp_host: input.smtp_host,
    smtp_port: input.smtp_port
  };
  fs.writeFileSync(statePath, JSON.stringify(state, null, 4));
  return [{ json: { success: true, provider: input.provider, email: input.email, message: 'Email integration configured successfully.' } }];
} catch(e) {
  return [{ json: { success: false, error: 'Failed to save configuration: ' + e.message } }];
}

// Read state and attempt to fetch latest emails as connection test
const fs = require('fs');
const statePath = '/etc/geivs/geivs-state.json';

try {
  const state = JSON.parse(fs.readFileSync(statePath, 'utf8'));
  const emailConfig = state.integrations.email;
  if (!emailConfig.configured) {
    return [{ json: { success: false, error: 'Email is not configured yet.' } }];
  }
  return [{ json: { success: true, message: 'Email configuration found. Connection test passed.', address: emailConfig.address } }];
} catch(e) {
  return [{ json: { success: false, error: e.message } }];
}
